    __m512d t39 = _mm512_sub_pd(t25, t29);
    __m512d t40 = _mm512_sub_pd(t26, t30);
    __m512d t41 = _mm512_add_pd(t33, t37);
    __m512d t42 = _mm512_add_pd(t34, t38);
    __m512d t43 = _mm512_sub_pd(t33, t37);
    __m512d t44 = _mm512_sub_pd(t34, t38);
    __m512d t45 = _mm512_add_pd(t35, t40);
    __m512d t46 = _mm512_sub_pd(t36, t39);
    __m512d t47 = _mm512_sub_pd(t35, t40);
    __m512d t48 = _mm512_add_pd(t36, t39);
    __m512d t49 = _mm512_add_pd(t19, t24);
    __m512d t50 = _mm512_sub_pd(t20, t23);
    __m512d t51 = _mm512_sub_pd(t19, t24);
    __m512d t52 = _mm512_add_pd(t20, t23);
    __m512d t53 = _mm512_set1_pd(0x1.6a09e667f3bcdp-1);
    __m512d t54 = _mm512_add_pd(t27, t32);
    __m512d t55 = _mm512_sub_pd(t28, t31);
    __m512d t56 = _mm512_add_pd(t54, t55);
    __m512d t57 = _mm512_mul_pd(t56, t53);
    __m512d t58 = _mm512_sub_pd(t55, t54);
    __m512d t59 = _mm512_mul_pd(t58, t53);
    __m512d t60 = _mm512_sub_pd(t27, t32);
    __m512d t61 = _mm512_add_pd(t28, t31);
    __m512d t62 = _mm512_sub_pd(t61, t60);
    __m512d t63 = _mm512_mul_pd(t62, t53);
    __m512d t64 = _mm512_add_pd(t61, t60);
    __m512d t65 = _mm512_mul_pd(t64, t53);
    __m512d t66 = _mm512_xor_pd(_mm512_set1_pd(-0.0), t65);
    __m512d t67 = _mm512_add_pd(t49, t57);
    __m512d t68 = _mm512_add_pd(t50, t59);
    __m512d t69 = _mm512_sub_pd(t49, t57);
    __m512d t70 = _mm512_sub_pd(t50, t59);
    __m512d t71 = _mm512_add_pd(t51, t63);
    __m512d t72 = _mm512_add_pd(t52, t66);
    __m512d t73 = _mm512_sub_pd(t51, t63);
